// Lấy danh sách item an toàn (tránh lỗi $input.all() khi gọi sub-workflow)
const items = $input.first() ?$input.all() : [];

const getField = (obj, fieldName) => {
  if (!obj) return "";
  if (obj[fieldName] !== undefined && obj[fieldName] !== null) {
    return obj[fieldName];
  }

  const actualKey = Object.keys(obj).find(
    key => key.trim() === fieldName.trim()
  );

  return actualKey !== undefined ? obj[actualKey] : "";
};

const normalize = value =>
  String(value ?? "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, " ")
    .trim()
    .replace(/\s+/g, " ");

const splitSkills = value =>
  String(value ?? "")
    .split(",")
    .map(s => s.trim())
    .filter(Boolean);

// Chỉ giữ các cặp CV - job có vị trí phù hợp
const matchingItems = items.filter(item => {
  const data = item.json;

  const appliedPosition = normalize(
    getField(data, "Vị trí ứng tuyển") ||
    getField(data, "applied_position")
  );

  const jobTitle = normalize(getField(data, "job_title"));
  const jobId = String(getField(data, "job_id") || "").trim();

  if (!appliedPosition || !jobTitle || !jobId) {
    return false;
  }

  return (
    appliedPosition === jobTitle ||
    appliedPosition.includes(jobTitle) ||
    jobTitle.includes(appliedPosition)
  );
});

// Loại bản ghi trùng theo email ứng viên + mã job
const seen = new Set();
const uniqueItems = matchingItems.filter(item => {
  const data = item.json;

  const email = normalize(
    getField(data, "Email") ||
    getField(data, "candidate_email")
  );

  const jobId = String(getField(data, "job_id") || "").trim();
  const key = `${email}|${jobId}`;

  if (seen.has(key)) return false;

  seen.add(key);
  return true;
});

// Nếu không tìm thấy bản ghi phù hợp, dùng mảng items ban đầu để duy trì luồng
const targetItems = uniqueItems.length > 0 ? uniqueItems : items;

return targetItems.map((item, index) => {
  const data = item.json || {};

  const candidateName =
    getField(data, "Họ và tên") ||
    getField(data, "candidate_name");

  const candidateEmail =
    getField(data, "Email") ||
    getField(data, "candidate_email");

  const skillsText =
    getField(data, "Kỹ năng") ||
    getField(data, "candidate_skills");

  const experienceText =
    getField(data, "Kinh nghiệm") ||
    getField(data, "candidate_experience");

  const jobId = String(getField(data, "job_id") || "").trim();
  const jobTitle = getField(data, "job_title");

  const appliedPosition =
    getField(data, "Vị trí ứng tuyển") ||
    getField(data, "applied_position") ||
    jobTitle;

  const requiredSkills = splitSkills(
    getField(data, "required_skills")
  );

  const preferredSkills = splitSkills(
    getField(data, "preferred_skills")
  );

  const candidateText = normalize(
    `${skillsText} ${experienceText}`
  );

  const matchedRequired = requiredSkills.filter(skill =>
    candidateText.includes(normalize(skill))
  );

  const missingRequired = requiredSkills.filter(skill =>
    !candidateText.includes(normalize(skill))
  );

  const matchedPreferred = preferredSkills.filter(skill =>
    candidateText.includes(normalize(skill))
  );

  const missingPreferred = preferredSkills.filter(skill =>
    !candidateText.includes(normalize(skill))
  );

  // Nhận diện kinh nghiệm theo từng nhóm nghề
  const normalizedPosition = normalize(jobTitle);
  const normalizedExperience = normalize(experienceText);

  let experienceKeywords = [];

  if (
    normalizedPosition.includes("backend") ||
    normalizedPosition.includes("developer")
  ) {
    experienceKeywords = [
      "backend", "back end", "rest api",
      "restful api", "spring boot", "software developer"
    ];
  } else if (
    normalizedPosition.includes("data analyst") ||
    normalizedPosition.includes("phan tich du lieu")
  ) {
    experienceKeywords = [
      "data analyst", "phan tich du lieu",
      "sql", "power bi", "tableau", "data analysis"
    ];
  } else if (
    normalizedPosition.includes("marketing") ||
    normalizedPosition.includes("truyen thong")
  ) {
    experienceKeywords = [
      "marketing", "truyen thong", "content",
      "social media", "copywriting", "digital marketing"
    ];
  }

  const hasRelevantExperience = experienceKeywords.some(
    keyword => normalizedExperience.includes(normalize(keyword))
  );

  const requiredRate = requiredSkills.length
    ? matchedRequired.length / requiredSkills.length
    : 0;

  const preferredRate = preferredSkills.length
    ? matchedPreferred.length / preferredSkills.length
    : 0;

  const experienceRate = hasRelevantExperience ? 1 : 0;

  const score = Math.round(
    (
      requiredRate * 0.7 +
      preferredRate * 0.2 +
      experienceRate * 0.1
    ) * 100
  ) / 10;

  let recommendation = "Low Match";

  if (score >= 8) {
    recommendation = "Strong Match";
  } else if (score >= 6) {
    recommendation = "Potential Match";
  }

  const reasons = [
    `Đáp ứng ${matchedRequired.length}/${requiredSkills.length} kỹ năng bắt buộc.`,
    `Đáp ứng ${matchedPreferred.length}/${preferredSkills.length} kỹ năng ưu tiên.`,
    hasRelevantExperience
      ? "Tìm thấy từ khóa kinh nghiệm liên quan đến vị trí."
      : "Chưa tìm thấy từ khóa kinh nghiệm liên quan rõ ràng."
  ];

  if (missingRequired.length) {
    reasons.push(
      `Kỹ năng bắt buộc cần kiểm tra thêm: ${missingRequired.join(", ")}.`
    );
  }

  return {
    json: {
      "Họ và tên ứng viên": candidateName,
      "Email ứng viên": candidateEmail,
      "Vị trí ứng tuyển": appliedPosition,
      "Mã tin tuyển dụng": jobId,
      "Tên vị trí tuyển dụng": jobTitle,

      "Điểm phù hợp": score,
      "Đề xuất đánh giá": recommendation,

      "Kỹ năng bắt buộc phù hợp": matchedRequired.join(", "),
      "Kỹ năng bắt buộc còn thiếu": missingRequired.join(", "),
      "Kỹ năng ưu tiên phù hợp": matchedPreferred.join(", "),
      "Kỹ năng ưu tiên còn thiếu": missingPreferred.join(", "),

      "Kinh nghiệm liên quan": hasRelevantExperience,
      "Lý do đánh giá": reasons.join(" "),
      "Phương pháp đánh giá": "Đối chiếu từ khóa theo quy tắc",
      "Thời gian đánh giá": new Date().toISOString(),

      "Quyết định của HR": "Pending Review",
      "Ngày phỏng vấn": "",
      "Giờ phỏng vấn": "",
      "Thời gian HR duyệt": "",
      "Trạng thái gửi email cho ứng viên": "Chưa gửi",
      "cv_row_number": getField(data, "row_number")
    },
    // Bổ sung pairedItem để giữ liên kết bản ghi cho các node tiếp theo
    pairedItem: {
      item: index
    }
  };
});

