{{ (() => {
  const SHEET_URL = "https://docs.google.com/spreadsheets/d/1kMrj8t9K3jPqjRcrOj0n5R7Mz7JV8STFlGlldKhzpBM/edit?gid=1446628200#gid=1446628200";

  const esc = (value) => String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");

  const list = (value) => {
    if (Array.isArray(value)) return value;
    if (value === null || value === undefined || value === "") return [];
    return String(value).split(",").map(s => s.trim()).filter(Boolean);
  };

  const tags = (items) => {
    if (!items.length) return '<span style="color:#777">Không có</span>';
    return items.map(s =>
      `<span style="display:inline-block;background:#eef2ff;color:#273c75;padding:5px 9px;margin:3px;border-radius:5px;">${esc(s)}</span>`
    ).join("");
  };

  const name = $json["Họ và tên ứng viên"] || "Chưa có thông tin";
const email = $json["Email ứng viên"] || "Chưa có thông tin";
const position = $json["Vị trí ứng tuyển"] || $json["Tên vị trí tuyển dụng"] || "Chưa xác định";
const jobId = $json["Mã tin tuyển dụng"] || "Chưa có";
const score = Number($json["Điểm phù hợp"] ?? 0);
const recommendation = $json["Đề xuất đánh giá"] || "Chưa có đánh giá";

const matchedRequired = list($json["Kỹ năng bắt buộc phù hợp"]);
const missingRequired = list($json["Kỹ năng bắt buộc còn thiếu"]);
const matchedPreferred = list($json["Kỹ năng ưu tiên phù hợp"]);
const missingPreferred = list($json["Kỹ năng ưu tiên còn thiếu"]);

const reason = $json["Lý do đánh giá"] || "Chưa có lý do đánh giá.";
const method = $json["Phương pháp đánh giá"] || "Đối chiếu từ khóa theo quy tắc";
const evaluatedAt = $json["Thời gian đánh giá"]
  ? new Date($json["Thời gian đánh giá"]).toLocaleString("vi-VN", {
      timeZone: "Asia/Ho_Chi_Minh"
    })
  : new Date().toLocaleString("vi-VN", {
      timeZone: "Asia/Ho_Chi_Minh"
    });

  const scoreColor = score >= 8 ? "#15803d" : score >= 6 ? "#b45309" : "#b91c1c";

  return `
  <div style="font-family:Arial,sans-serif;max-width:700px;margin:auto;color:#222;line-height:1.6;">
    <div style="background:#17365d;color:#fff;padding:22px;border-radius:8px 8px 0 0;">
      <h2 style="margin:0;">BÁO CÁO ĐÁNH GIÁ CV</h2>
      <p style="margin:6px 0 0;">Hệ thống hỗ trợ sàng lọc hồ sơ ứng viên</p>
    </div>

    <div style="border:1px solid #ddd;padding:22px;border-radius:0 0 8px 8px;">
      <p>Kính gửi Bộ phận Nhân sự,</p>
      <p>Hệ thống đã hoàn thành đánh giá sơ bộ hồ sơ ứng viên. Vui lòng xem thông tin dưới đây và kiểm tra CV trước khi đưa ra quyết định cuối cùng.</p>

      <h3 style="color:#17365d;border-bottom:1px solid #ddd;padding-bottom:7px;">1. Thông tin ứng viên</h3>
      <table style="width:100%;border-collapse:collapse;">
        <tr><td style="padding:7px;border-bottom:1px solid #eee;width:38%;"><b>Họ và tên</b></td><td style="padding:7px;border-bottom:1px solid #eee;">${esc(name)}</td></tr>
        <tr><td style="padding:7px;border-bottom:1px solid #eee;"><b>Email</b></td><td style="padding:7px;border-bottom:1px solid #eee;">${esc(email)}</td></tr>
        <tr><td style="padding:7px;border-bottom:1px solid #eee;"><b>Vị trí ứng tuyển</b></td><td style="padding:7px;border-bottom:1px solid #eee;">${esc(position)}</td></tr>
        <tr><td style="padding:7px;border-bottom:1px solid #eee;"><b>Mã tin tuyển dụng</b></td><td style="padding:7px;border-bottom:1px solid #eee;">${esc(jobId)}</td></tr>
      </table>

      <h3 style="color:#17365d;border-bottom:1px solid #ddd;padding-bottom:7px;">2. Kết quả đánh giá</h3>
      <div style="text-align:center;background:#f8fafc;padding:18px;border-radius:8px;">
        <div style="font-size:14px;color:#555;">Điểm phù hợp</div>
        <div style="font-size:38px;font-weight:bold;color:${scoreColor};">${esc(score)}/10</div>
        <div style="font-size:17px;font-weight:bold;color:${scoreColor};">${esc(recommendation)}</div>
      </div>

      <h4>Kỹ năng bắt buộc phù hợp</h4>
      <div>${tags(matchedRequired)}</div>

      <h4>Kỹ năng bắt buộc còn thiếu</h4>
      <div>${tags(missingRequired)}</div>

      <h4>Kỹ năng ưu tiên phù hợp</h4>
      <div>${tags(matchedPreferred)}</div>

      <h4>Kỹ năng ưu tiên còn thiếu</h4>
      <div>${tags(missingPreferred)}</div>

      <h3 style="color:#17365d;border-bottom:1px solid #ddd;padding-bottom:7px;">3. Lý do đánh giá</h3>
      <p>${esc(reason)}</p>

      <p><b>Phương pháp:</b> ${esc(method)}</p>
      <p><b>Thời gian đánh giá:</b> ${esc(evaluatedAt)}</p>

      <div style="text-align:center;margin:28px 0;">
        <a href="${SHEET_URL}" style="display:inline-block;background:#17365d;color:#fff;text-decoration:none;padding:13px 22px;border-radius:6px;font-weight:bold;">
          MỞ GOOGLE SHEETS ĐỂ DUYỆT CV
        </a>
      </div>

      <p><b>Hướng dẫn cho HR:</b></p>
      <ol>
        <li>Nhấn nút phía trên để mở bảng kết quả.</li>
        <li>Tìm hồ sơ ứng viên cần xem xét.</li>
        <li>Cập nhật cột <b>HR_Decision</b>: Pending Review, Approve hoặc Reject.</li>
        <li>Có thể ghi nhận xét tại cột <b>HR_Comment</b>.</li>
      </ol>

      <p style="background:#fff7ed;padding:12px;border-left:4px solid #f59e0b;">
        <b>Lưu ý:</b> Điểm số là kết quả đối chiếu từ khóa tự động, chỉ mang tính tham khảo và không thay thế việc HR xem xét CV thực tế.
      </p>

      <p>Trân trọng,<br><b>Hệ thống CV Matching & Notification</b></p>
    </div>
  </div>
  `;
})() }}
